#!/usr/bin/env node
/**
 * Tests for workflows/impl-review-loop.js: reviewer fan-out, sizing and the wide-change Opus, coverage of the files read, and snapshots.
 * Zero dependencies — `node:test` on Node 18+; the shared harness is tools/impl-review-loop.harness.mjs.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { f, ROOT, snapshot, run, ARGS, review, finding, MANY, manyArgs, manyImpl, read, impl, defect, unreviewedFiles, reviewersFor, sizeFor, readReport, coverageAction, coverageOwners, riskAxes, sizeSignal, isReview, reviewLabels } from './impl-review-loop.harness.mjs';

// ── reviewer budget, an agent that throws ─────────────────────────────────
test('reviewersFor: S one Sonnet at high, M one Sonnet at high, L Sonnet and Opus at high; specialists at M and L only when touched', () => {
  const spec = (size, touches) => reviewersFor(size, touches).map((r) => `${r.key}:${r.agentType}:${r.model}:${r.effort}${r.whole ? ':whole' : ''}`);
  assert.deepEqual(spec('S', []), ['A:code-reviewer:sonnet:high:whole']);
  assert.deepEqual(spec('M', []), ['A:code-reviewer:sonnet:high:whole']);
  assert.deepEqual(spec('L', []), ['A:code-reviewer:sonnet:high:whole', 'B:code-reviewer:opus:high:whole']);
  assert.deepEqual(spec('S', ['security', 'performance']), ['A:code-reviewer:sonnet:high:whole']);
  assert.deepEqual(spec('M', ['security']), ['A:code-reviewer:sonnet:high:whole', 'security:review-security:sonnet:high']);
  assert.deepEqual(spec('L', ['performance', 'security']).slice(2), ['security:review-security:sonnet:high', 'performance:review-performance:sonnet:medium']);
  assert.deepEqual(spec('M', undefined), ['A:code-reviewer:sonnet:high:whole']);
  assert.deepEqual(reviewersFor('S', [], true).map((r) => `${r.model}:${r.effort}`), ['sonnet:low']);
  assert.deepEqual(reviewersFor('M', [], true).map((r) => `${r.model}:${r.effort}`), ['sonnet:high']);
});

test('sizeFor: the triage size stands; data/money/concurrency/contract/security lift S to M, three axes besides logic lift to L, never downward', () => {
  assert.equal(sizeFor('S', []), 'S');
  assert.equal(sizeFor('S'), 'S');
  assert.equal(sizeFor('S', ['logic']), 'S');
  assert.equal(sizeFor('S', ['logic', 'performance']), 'S');                 // two axes of the low kind
  for (const axis of ['data', 'money', 'concurrency', 'contract', 'security']) assert.equal(sizeFor('S', [axis]), 'M', axis);
  assert.equal(sizeFor('S', ['logic', 'performance', 'security']), 'M');    // logic is in almost every change: it never counts toward L
  assert.equal(sizeFor('M', ['logic', 'performance', 'data']), 'M');
  assert.equal(sizeFor('S', ['performance', 'data', 'security']), 'L');
  assert.equal(sizeFor('M', ['data']), 'M');
  assert.equal(sizeFor('L', []), 'L');
  assert.equal(sizeFor('L', ['logic']), 'L');
  assert.equal(sizeFor('bogus', ['data']), 'M');
});

test('riskAxes: risk and the old touches merge, unknown values and repeats are dropped', () => {
  assert.deepEqual(riskAxes(['data', 'logic'], ['security', 'data', 'bogus']), ['data', 'logic', 'security']);
  assert.deepEqual(riskAxes(undefined, ['performance']), ['performance']);
  assert.deepEqual(riskAxes('data', null), []);
});

test('sizeSignal: more files than the triage size implies is a signal (S > 1 file, M > 6), L never', () => {
  assert.equal(sizeSignal('S', 1), '');
  assert.match(sizeSignal('S', 2), /2 files.*size S/);
  assert.equal(sizeSignal('M', 6), '');
  assert.match(sizeSignal('M', 7), /7 files.*size M/);
  assert.equal(sizeSignal('L', 40), '');
});

test('readReport: a report without verify is not-run, without rejected/noticed empty, without snapshot null', () => {
  const r = readReport({ scope: 's', files: ['a.cs'], evidence: 'ok' });
  assert.deepEqual(r.verify, { status: 'not-run' });
  assert.deepEqual(r.rejected, []);
  assert.deepEqual(r.noticed, []);
  assert.deepEqual(r.questions, []);
  assert.deepEqual(r.filesReviewed, []);
  assert.equal(r.snapshot, null);
  assert.deepEqual(r.files, ['a.cs']);
  const full = { verify: { status: 'fail', command: 'dotnet test', line: 'Failed: 2' }, snapshot: { tree: 't', files: ['a.cs'], churn: 4 }, rejected: [{ id: 'F1', reason: 'not reproduced' }], noticed: [{ title: 't', path: 'p', why: 'w' }], questions: [{ text: 'q', default: 'd', why: 'w' }], filesReviewed: ['a.cs'] };
  assert.deepEqual(readReport(full), { ...full, defaults: [], remaining: [] });
  assert.deepEqual(readReport({ questions: [{ text: 'q' }, { text: ' ' }, { default: 'd' }, null, 'q'] }).questions, [{ text: 'q' }]);
  assert.deepEqual(readReport({ verify: { status: 'green', command: 'x' } }).verify, { status: 'not-run', command: 'x' });
  assert.equal(readReport(null), null);
});


test('script: every reviewer and fixer prompt carries the tool-call budget; the implement prompt does not, and leaves the targeted-tests rule to the agent body', async () => {
  const { calls } = await run(ARGS, [review([], [finding()]), review([{ id: 'F1', status: 'closed' }])]);
  for (const c of calls.filter(c => c.opts.label !== 'implement the change')) assert.match(c.prompt, /TOOL BUDGET: at most \d+ tool calls.*partial result beats none/s, c.opts.label);
  const implement = calls.find(c => c.opts.label === 'implement the change').prompt;
  assert.doesNotMatch(implement, /TOOL BUDGET/);
  assert.doesNotMatch(implement, /run only the test files your change touches/);
});

